#include <bits/stdc++.h>
using namespace std;
using ll = long long;

struct Dinic {
    struct Edge {
        int to, rev;
        ll cap;
    };

    vector<vector<Edge>> g;
    vector<int> level, ptr;
    int src, sink;

    Dinic(int n, int s, int t) : g(n), level(n), ptr(n), src(s), sink(t) {}

    void add_edge(int u, int v, ll cap) {
        g[u].push_back({v, (int)g[v].size(), cap});
        g[v].push_back({u, (int)g[u].size()-1, 0});
    }

    bool bfs() {
        fill(level.begin(), level.end(), -1);
        level[src] = 0;
        queue<int> q; q.push(src);
        while (!q.empty()) {
            int u = q.front(); q.pop();
            for (auto &e : g[u]) {
                if (e.cap > 0 && level[e.to] == -1) {
                    level[e.to] = level[u] + 1;
                    q.push(e.to);
                }
            }
        }
        return level[sink] != -1;
    }

    ll dfs(int u, ll flow) {
        if (u == sink) return flow;
        for (int &i = ptr[u]; i < (int)g[u].size(); ++i) {
            auto &e = g[u][i];
            if (e.cap > 0 && level[e.to] == level[u] + 1) {
                ll pushed = dfs(e.to, min(flow, e.cap));
                if (pushed > 0) {
                    e.cap -= pushed;
                    g[e.to][e.rev].cap += pushed;
                    return pushed;
                }
            }
        }
        return 0;
    }

    ll max_flow() {
        ll result = 0;
        while (bfs()) {
            fill(ptr.begin(), ptr.end(), 0);
            while (ll pushed = dfs(src, 1e18)) {
                result += pushed;
            }
        }
        return result;
    }
};

int main() {
    ios::sync_with_stdio(false); cin.tie(nullptr);

    int n, T;
    cin >> n >> T;

    vector<string> grid(n);
    int start_y = -1, start_x = -1;
    for (int i = 0; i < n; ++i) {
        cin >> grid[i];
        for (int j = 0; j < n; ++j) {
            if (grid[i][j] == 'Z') {
                start_y = i;
                start_x = j;
            }
        }
    }

    string dummy;
    getline(cin, dummy);
    getline(cin, dummy);

    vector<string> exits(n);
    for (int i = 0; i < n; ++i) {
        cin >> exits[i];
    }

    vector<vector<int>> dist(n, vector<int>(n, -1));
    queue<pair<int, int>> q;
    q.push({start_y, start_x});
    dist[start_y][start_x] = 0;

    const int dy[] = {1, -1, 0, 0};
    const int dx[] = {0, 0, 1, -1};

    while (!q.empty()) {
        auto [y, x] = q.front(); q.pop();
        for (int d = 0; d < 4; ++d) {
            int ny = y + dy[d], nx = x + dx[d];
            if (ny < 0 || ny >= n || nx < 0 || nx >= n) continue;
            if (dist[ny][nx] != -1 || grid[ny][nx] == 'Y') continue;
            dist[ny][nx] = dist[y][x] + 1;
            if (dist[ny][nx] < T) {
                q.push({ny, nx});
            }
        }
    }

    for (int i = 0; i < n; ++i) {
        for (int j = 0; j < n; ++j) {
            if (grid[i][j] >= '0' && grid[i][j] <= '9') {
                if (dist[i][j] == -1) dist[i][j] = T;
                else dist[i][j] = min(dist[i][j], T);
            }
        }
    }

    vector<vector<int>> node_id(n, vector<int>(n, -1));
    int node_count = 0;

    for (int i = 0; i < n; ++i) {
        for (int j = 0; j < n; ++j) {
            if (grid[i][j] >= '0' && grid[i][j] <= '9') {
                node_id[i][j] = node_count++;
            }
            if (exits[i][j] >= '1' && exits[i][j] <= '9') {
                node_id[i][j] = node_count++;
            }
        }
    }

    int source = 0, sink = node_count + 1;
    Dinic flow(node_count + 2, source, sink);

    for (int i = 0; i < n; ++i) {
        for (int j = 0; j < n; ++j) {
            if (grid[i][j] >= '1' && grid[i][j] <= '9') {
                flow.add_edge(source, node_id[i][j], grid[i][j] - '0');
            }

            if (exits[i][j] >= '1' && exits[i][j] <= '9') {
                flow.add_edge(node_id[i][j], sink, exits[i][j] - '0');
            }

            for (int d = 0; d < 4; ++d) {
                int ni = i + dy[d], nj = j + dx[d];
                if (ni < 0 || ni >= n || nj < 0 || nj >= n) continue;
                if (grid[ni][nj] == 'Y' || grid[ni][nj] == 'Z') continue;

                if (node_id[i][j] != -1 && node_id[ni][nj] != -1) {
                    flow.add_edge(node_id[i][j], node_id[ni][nj], 1e9);
                }
            }
        }
    }

    cout << flow.max_flow() << '\n';
    return 0;
}
